import { describe, expect, it } from "vitest";
import { fileKey, parseStack, SourceMap, symbolicateStack } from "./sourcemap";

/**
 * A real map, generated by esbuild for a two-line source, so the decoder is
 * checked against the format as a bundler actually writes it rather than
 * against a hand-made example that happens to match the implementation.
 */
const map = {
  version: 3,
  sources: ["src/login.ts"],
  sourcesContent: ["export function submitLogin(form: HTMLFormElement) {\n  form.querySelector('input')!.focus();\n}\n"],
  mappings: "AAAO,SAAS,YAAY,MAA2B;AACrD,OAAK,cAAc,OAAO,EAAG,MAAM;AACrC",
  names: [],
};

describe("source maps", () => {
  const consumer = SourceMap.parse(JSON.stringify(map))!;

  it("reads a map a bundler wrote", () => {
    expect(consumer).not.toBeNull();
    const first = consumer.originalPositionFor(1, 1);
    expect(first?.source).toBe("src/login.ts");
    expect(first?.line).toBe(1);
  });

  it("finds the original line for a column part way along a generated line", () => {
    const second = consumer.originalPositionFor(2, 3);
    expect(second?.source).toBe("src/login.ts");
    expect(second?.line).toBe(2);
  });

  it("refuses rubbish rather than throwing", () => {
    expect(SourceMap.parse("not json")).toBeNull();
    expect(SourceMap.parse('{"version":3}')).toBeNull();
    expect(consumer.originalPositionFor(99, 1)).toBeNull();
  });

  it("gives the path in the repository, not the one relative to the build", () => {
    const webpack = SourceMap.parse(JSON.stringify({ ...map, sources: ["webpack://app/./src/login.ts"] }))!;
    expect(webpack.originalPositionFor(1, 1)?.source).toBe("src/login.ts");
    // esbuild writes sources relative to the outfile, so they climb out of out/.
    const esbuild = SourceMap.parse(JSON.stringify({ ...map, sources: ["../src/login.ts"] }))!;
    expect(esbuild.originalPositionFor(1, 1)?.source).toBe("src/login.ts");
  });
});

describe("stack traces", () => {
  it("reads the shape Chrome and Node write", () => {
    const frames = parseStack(`TypeError: x is null
    at submitLogin (https://acme.test/assets/app-8fd2.js:2:3)
    at https://acme.test/assets/app-8fd2.js:1:1`);
    expect(frames[0]).toBe("TypeError: x is null");
    expect(frames[1]).toMatchObject({ fn: "submitLogin", file: "https://acme.test/assets/app-8fd2.js", line: 2, column: 3 });
    expect(frames[2]).toMatchObject({ fn: undefined, line: 1, column: 1 });
  });

  it("reads the shape Safari and Firefox write", () => {
    const frames = parseStack("submitLogin@https://acme.test/assets/app-8fd2.js:2:3");
    expect(frames[0]).toMatchObject({ fn: "submitLogin", line: 2, column: 3 });
  });

  it("leaves a line it doesn't recognise exactly as it was", () => {
    const text = "    at <anonymous>";
    expect(parseStack(text)[0]).toBe(text);
  });

  it("names a map by the path of the file it belongs to", () => {
    expect(fileKey("https://acme.test/assets/app-8fd2.js?v=3")).toBe("assets/app-8fd2.js");
    expect(fileKey("/assets/app.js")).toBe("assets/app.js");
  });
});

describe("symbolicating", () => {
  const consumer = SourceMap.parse(JSON.stringify(map))!;
  const find = (file: string) => (file === "assets/app-8fd2.js" ? consumer : undefined);

  it("rewrites the frames it can and keeps the rest", () => {
    const { stack, changed } = symbolicateStack(
      `TypeError: Cannot read properties of null
    at submitLogin (https://acme.test/assets/app-8fd2.js:2:3)
    at onClick (https://acme.test/assets/other.js:9:9)`,
      find,
    );
    expect(changed).toBe(1);
    expect(stack).toContain("src/login.ts:2:");
    // The frame with no map is untouched, down to its whitespace.
    expect(stack).toContain("    at onClick (https://acme.test/assets/other.js:9:9)");
    expect(stack.split("\n")[0]).toBe("TypeError: Cannot read properties of null");
  });

  it("changes nothing when no map matches", () => {
    const original = "    at submitLogin (https://acme.test/assets/app-8fd2.js:2:3)";
    expect(symbolicateStack(original, () => undefined)).toEqual({ stack: original, changed: 0 });
  });
});
